// A small C shim between Rust and the Lean runtime.
//
// The helpers in `lean.h` for building and reading byte arrays are `static inline`, so Rust
// cannot call them directly. This file wraps them, together with runtime initialization, in a
// few plain C functions.

#include <lean/lean.h>
#include <string.h>

// Declared by the Lean runtime but not in `lean.h`.
extern void lean_initialize_runtime_module(void);
extern void lean_initialize_thread(void);

// Generated by Lean for the root module `HashFFI` of the package `hash-specs`.
extern lean_object *runtime_initialize_hash_x2dspecs_x2dzk_HashFFI(uint8_t builtin);

typedef lean_object *(*hs_fn)(lean_object *);

// Initialize the Lean runtime and the exported modules. Must be called once, before any other
// function here. Returns 0 on success.
int hs_init(void) {
  lean_object *res = runtime_initialize_hash_x2dspecs_x2dzk_HashFFI(1);
  int ok = lean_io_result_is_ok(res);
  lean_dec_ref(res);
  lean_io_mark_end_initialization();
  return ok ? 0 : 1;
}

// Prepare the current thread for calling into Lean. Must be called once on every thread other
// than the one that called `hs_init`.
void hs_init_thread(void) { lean_initialize_thread(); }

// Call an exported `ByteArray → ByteArray` function on `len` bytes at `in`. Copies at most `cap`
// bytes of the result to `out` and returns the full length of the result.
size_t hs_call_bytes(hs_fn f, const uint8_t *in, size_t len, uint8_t *out, size_t cap) {
  lean_object *arg = lean_alloc_sarray(1, len, len);
  if (len > 0) memcpy(lean_sarray_cptr(arg), in, len);
  lean_object *res = f(arg);  // consumes `arg`
  size_t n = lean_sarray_size(res);
  memcpy(out, lean_sarray_cptr(res), n < cap ? n : cap);
  lean_dec(res);
  return n;
}
